{"title": "Top 10 Matched IPs · Alert Evidence", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Actual IP match evidence from this rule's threat.enrichments; not endpoint IP guesses.",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": {
    "left": 150,
    "right": 20,
    "top": 15,
    "bottom": 45
  },
  "data": [
    {
      "name": "matched_ips",
      "url": {
        "index": ".alerts-security.alerts-default",
        "body": {
          "size": 0,
          "query": {
            "bool": {
              "must": [
                "%dashboard_context-must_clause%"
              ],
              "filter": [
                "%dashboard_context-filter_clause%",
                {
                  "term": {
                    "kibana.alert.rule.rule_id": "66f68655-8d93-4f42-824e-e6048b386207"
                  }
                },
                {
                  "range": {
                    "@timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "term": {
                    "tags": "synthetic"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "aggs": {
            "enrichments": {
              "nested": {
                "path": "threat.enrichments"
              },
              "aggs": {
                "ip_matches": {
                  "filter": {
                    "bool": {
                      "filter": [
                        {
                          "terms": {
                            "threat.enrichments.matched.field": [
                              "source.ip",
                              "destination.ip"
                            ]
                          }
                        },
                        {
                          "term": {
                            "threat.enrichments.matched.type": "indicator_match_rule"
                          }
                        }
                      ]
                    }
                  },
                  "aggs": {
                    "ips": {
                      "terms": {
                        "field": "threat.enrichments.matched.atomic",
                        "size": 10,
                        "shard_size": 100,
                        "order": {
                          "alerts": "desc"
                        }
                      },
                      "aggs": {
                        "alerts": {
                          "reverse_nested": {}
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.enrichments.ip_matches.ips.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.alerts.doc_count",
          "as": "alert_count"
        },
        {
          "type": "collect",
          "sort": {
            "field": "alert_count",
            "order": "descending"
          }
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "y",
      "type": "band",
      "domain": {
        "data": "matched_ips",
        "field": "key"
      },
      "range": "height",
      "padding": 0.2
    },
    {
      "name": "x",
      "type": "linear",
      "range": "width",
      "zero": true,
      "nice": true,
      "domain": {
        "signal": "length(data('matched_ips')) ? [0, max(1, extent(pluck(data('matched_ips'), 'alert_count'))[1])] : [0, 1]"
      }
    }
  ],
  "axes": [
    {
      "orient": "left",
      "scale": "y",
      "title": "Matched IP",
      "labelLimit": 145,
      "labelColor": "#cbd5e1",
      "titleColor": "#94a3b8"
    },
    {
      "orient": "bottom",
      "scale": "x",
      "title": "Related Alerts",
      "tickMinStep": 1,
      "labelColor": "#cbd5e1",
      "titleColor": "#94a3b8"
    }
  ],
  "marks": [
    {
      "type": "rect",
      "from": {
        "data": "matched_ips"
      },
      "encode": {
        "update": {
          "x": {
            "scale": "x",
            "value": 0
          },
          "x2": {
            "scale": "x",
            "field": "alert_count"
          },
          "y": {
            "scale": "y",
            "field": "key"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "fill": {
            "value": "#5487e0"
          },
          "tooltip": {
            "signal": "{'Matched IP': datum.key, 'Related Alerts': datum.alert_count}"
          }
        }
      }
    },
    {
      "type": "text",
      "encode": {
        "update": {
          "x": {
            "signal": "width / 2"
          },
          "y": {
            "signal": "height / 2"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fill": {
            "value": "#94a3b8"
          },
          "fontSize": {
            "value": 14
          },
          "text": {
            "signal": "length(data('matched_ips')) ? '' : 'No alerts with matched IP evidence'"
          }
        }
      }
    }
  ]
}"}}
